const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const lakeErie = ee.Geometry.Polygon([[
        [-83.54, 42.90], [-78.85, 42.90], [-78.85, 41.35],
        [-83.54, 41.35], [-83.54, 42.90]
    ]]);
    const date1 = '2014-01-09';
    const date2 = '2014-01-14';
    const imageCollection = 'MODIS/061/MOD10A1';
    const bandName = 'NDSI_Snow_Cover';
    const scale = 1000;

    // 2. Data Acquisition & Check
    const image1_col = ee.ImageCollection(imageCollection)
        .filterDate(date1, ee.Date(date1).advance(1, 'day'))
        .filterBounds(lakeErie);

    const image2_col = ee.ImageCollection(imageCollection)
        .filterDate(date2, ee.Date(date2).advance(1, 'day'))
        .filterBounds(lakeErie);

    const count1 = image1_col.size().getInfo();
    const count2 = image2_col.size().getInfo();

    if (count1 === 0 || count2 === 0) {
        console.log(`Image count for ${date1}: ${count1}`);
        console.log(`Image count for ${date2}: ${count2}`);
        console.log("Empty Collection: No images found for one or both dates.");
        console.log("A"); // The user is asking a Yes/No question, and C1 is not an option for this question. A is printed instead of C1.
        return;
    }

    const image1 = image1_col.first().clip(lakeErie);
    const image2 = image2_col.first().clip(lakeErie);

    // 3. Processing: Create a binary mask for ice cover
    // NDSI values > 40 are generally considered snow/ice.
    const iceThreshold = 40;
    const ice1 = image1.select(bandName).gte(iceThreshold);
    const ice2 = image2.select(bandName).gte(iceThreshold);

    // 4. Calculation: Calculate the area of ice for each date
    const iceArea1_calc = ice1.multiply(ee.Image.pixelArea()).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: lakeErie,
        scale: scale,
        maxPixels: 1e9
    });

    const iceArea2_calc = ice2.multiply(ee.Image.pixelArea()).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: lakeErie,
        scale: scale,
        maxPixels: 1e9
    });

    // Using ee.Dictionary.get is safer than .getInfo() directly on the result
    const iceArea1 = ee.Number(iceArea1_calc.get(bandName));
    const iceArea2 = ee.Number(iceArea2_calc.get(bandName));

    const results = ee.Dictionary({
        area1: iceArea1,
        area2: iceArea2
    }).getInfo();

    const area1_sqkm = results.area1 / 1e6;
    const area2_sqkm = results.area2 / 1e6;

    // 5. Validation & Final Answer
    if (results.area1 === null || results.area2 === null) {
        console.log(`Ice Area ${date1}: ${results.area1}`);
        console.log(`Ice Area ${date2}: ${results.area2}`);
        console.log("Calculation Failure: Could not compute ice area.");
        console.log("C3");
        return;
    }

    if (area1_sqkm === 0 && area2_sqkm === 0) {
        console.log(`Ice Area ${date1}: 0.00 sq km`);
        console.log(`Ice Area ${date2}: 0.00 sq km`);
        console.log("No valid pixels to calculate ice cover for both dates.");
        console.log("C2");
        return;
    }

    console.log(`Ice Cover on ${date1}: ${area1_sqkm.toFixed(2)} sq km`);
    console.log(`Ice Cover on ${date2}: ${area2_sqkm.toFixed(2)} sq km`);

    if (area2_sqkm < area1_sqkm) {
        console.log("Conclusion: Ice cover extent decreased.");
        console.log("A");
    } else {
        console.log("Conclusion: Ice cover extent did not decrease (it increased or stayed the same).");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
